import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"41、【损】 兑下艮上","description":"横渠易说 - 41、【损】 兑下艮上","frontmatter":{"title":"41、【损】 兑下艮上","description":"横渠易说 - 41、【损】 兑下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/043.md","filePath":"zh/classics/hengqu/043.md"}'),l={name:"zh/classics/hengqu/043.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_41、【损】-兑下艮上" tabindex="-1">41、【损】 兑下艮上 <a class="header-anchor" href="#_41、【损】-兑下艮上" aria-label="Permalink to “41、【损】 兑下艮上”">​</a></h1><h3 id="彖曰-损-损下益上-其道上行。损而有孚元吉-无咎可贞-利有攸往。-曷之用-二簋可用享-二簋应有时-损刚益柔有时-损益盈虚-与时偕行。" tabindex="-1">彖曰：损，损下益上，其道上行。损而有孚元吉，无咎可贞，利有攸往。“曷之用？二簋可用享”，二簋应有时，损刚益柔有时，损益盈虚，与时偕行。 <a class="header-anchor" href="#彖曰-损-损下益上-其道上行。损而有孚元吉-无咎可贞-利有攸往。-曷之用-二簋可用享-二簋应有时-损刚益柔有时-损益盈虚-与时偕行。" aria-label="Permalink to “彖曰：损，损下益上，其道上行。损而有孚元吉，无咎可贞，利有攸往。“曷之用？二簋可用享”，二簋应有时，损刚益柔有时，损益盈虚，与时偕行。”">​</a></h3><h3 id="象曰-山下有泽-损-君子以惩忿窒欲。" tabindex="-1">象曰：山下有泽，损，君子以惩忿窒欲。 <a class="header-anchor" href="#象曰-山下有泽-损-君子以惩忿窒欲。" aria-label="Permalink to “象曰：山下有泽，损，君子以惩忿窒欲。”">​</a></h3><p>损下益上，损刚益柔，非可常行，必有孚元吉，无咎可贞，然后利有所进，故下云“有时”。</p><h3 id="初九-已事遄往-无咎-酌损之。-象曰-已事遄往-尚合志也。" tabindex="-1">初九，已事遄往，无咎，酌损之。 象曰：“已事遄往”，尚合志也。 <a class="header-anchor" href="#初九-已事遄往-无咎-酌损之。-象曰-已事遄往-尚合志也。" aria-label="Permalink to “初九，已事遄往，无咎，酌损之。 象曰：“已事遄往”，尚合志也。”">​</a></h3><p>损刚益柔有时，损不可过，抑而居下，有为而然，故事已则当速反于上，与四合志。损不以中，未免于咎也。</p><h3 id="九二-利贞-征凶-弗损益之。-象曰-九二利贞-中以为志也。" tabindex="-1">九二，利贞，征凶，弗损益之。 象曰：“九二利贞”，中以为志也。 <a class="header-anchor" href="#九二-利贞-征凶-弗损益之。-象曰-九二利贞-中以为志也。" aria-label="Permalink to “九二，利贞，征凶，弗损益之。 象曰：“九二利贞”，中以为志也。”">​</a></h3><p>以阳居阴，刚德已损，故以征则凶。能志于正，则虽损非损，其实受益。</p><h3 id="六三-三人行则损一人-一人行则得其友。-象曰-一人行-三则疑也。" tabindex="-1">六三，三人行则损一人，一人行则得其友。 象曰：一人行，三则疑也。 <a class="header-anchor" href="#六三-三人行则损一人-一人行则得其友。-象曰-一人行-三则疑也。" aria-label="Permalink to “六三，三人行则损一人，一人行则得其友。 象曰：一人行，三则疑也。”">​</a></h3><p>六三本为上六，与坤同体，若连茹汇征，三人并行，则反非益上之道也。</p><h3 id="六四-损其疾-使遄有喜-无咎。-象曰-损其疾-亦可喜也。" tabindex="-1">六四，损其疾，使遄有喜，无咎。 象曰：“损其疾”，亦可喜也。 <a class="header-anchor" href="#六四-损其疾-使遄有喜-无咎。-象曰-损其疾-亦可喜也。" aria-label="Permalink to “六四，损其疾，使遄有喜，无咎。 象曰：“损其疾”，亦可喜也。”">​</a></h3><p>六三志应于上，近不相得，不固其路使速应于上，则初九之应无所间阻，故曰“损其疾”，使彼有喜，故己亦可喜而无咎也。</p><h3 id="六五-或益之十朋之龟-弗克违-元吉。-象曰-六五元吉-自上祐也。" tabindex="-1">六五，或益之十朋之龟，弗克违，元吉。 象曰：六五元吉，自上祐也。 <a class="header-anchor" href="#六五-或益之十朋之龟-弗克违-元吉。-象曰-六五元吉-自上祐也。" aria-label="Permalink to “六五，或益之十朋之龟，弗克违，元吉。 象曰：六五元吉，自上祐也。”">​</a></h3><p>龟弗能远，言受益之可必，信然不疑也。“或益之”，上九自外来而比之，况其下者乎!</p><h3 id="上九-弗损益之-无咎-贞吉。利有攸往-得臣无家。-象曰-弗损益之-大得志也。" tabindex="-1">上九，弗损益之，无咎，贞吉。利有攸往，得臣无家。 象曰：“弗损益之”，大得志也。 <a class="header-anchor" href="#上九-弗损益之-无咎-贞吉。利有攸往-得臣无家。-象曰-弗损益之-大得志也。" aria-label="Permalink to “上九，弗损益之，无咎，贞吉。利有攸往，得臣无家。 象曰：“弗损益之”，大得志也。”">​</a></h3><p>上九本为九三，虽为损下，其实上行，故云“弗损益之”。损终反益，反如益卦损上而益下，则可大得志，至于得臣无家，(咎)［言］所有之多也。以刚在上，受下之益多矣，故(大川)［无所］施损，当反益于下，故曰“弗损益之”。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
